17	package com.google.zxing.oned.rss;
18	
19	import com.google.zxing.NotFoundException;
20	import com.google.zxing.common.detector.MathUtils;
21	import com.google.zxing.oned.OneDReader;
22	
23	/**
24	 * Superclass of {@link OneDReader} implementations that read barcodes in the RSS family
25	 * of formats.
26	 */
27	public abstract class AbstractRSSReader extends OneDReader {
28	
29	  private static final float MAX_AVG_VARIANCE = 0.2f;
30	  private static final float MAX_INDIVIDUAL_VARIANCE = 0.45f;
31	
32	  /** Minimum ratio 10:12 (minus 0.5 for variance), from section 7.2.7 of ISO/IEC 24724:2006. */
33	  private static final float MIN_FINDER_PATTERN_RATIO = 9.5f / 12.0f;
34	  /** Maximum ratio 12:14 (plus 0.5 for variance), from section 7.2.7 of ISO/IEC 24724:2006. */
35	  private static final float MAX_FINDER_PATTERN_RATIO = 12.5f / 14.0f;
36	
37	  private final int[] decodeFinderCounters;
38	  private final int[] dataCharacterCounters;
39	  private final float[] oddRoundingErrors;
40	  private final float[] evenRoundingErrors;
41	  private final int[] oddCounts;
42	  private final int[] evenCounts;
43	
44	  protected AbstractRSSReader() {
45	    decodeFinderCounters = new int[4];
46	    dataCharacterCounters = new int[8];
47	    oddRoundingErrors = new float[4];
48	    evenRoundingErrors = new float[4];
49	    oddCounts = new int[dataCharacterCounters.length / 2];
50	    evenCounts = new int[dataCharacterCounters.length / 2];
51	  }
52	
53	  protected final int[] getDecodeFinderCounters() {
54	    return decodeFinderCounters;
55	  }
56	
57	  protected final int[] getDataCharacterCounters() {
58	    return dataCharacterCounters;
59	  }
60	
61	  protected final float[] getOddRoundingErrors() {
62	    return oddRoundingErrors;
63	  }
64	
65	  protected final float[] getEvenRoundingErrors() {
66	    return evenRoundingErrors;
67	  }
68	
69	  protected final int[] getOddCounts() {
70	    return oddCounts;
71	  }
72	
73	  protected final int[] getEvenCounts() {
74	    return evenCounts;
75	  }
76	
77	  protected static int parseFinderValue(int[] counters,
78	                                        int[][] finderPatterns) throws NotFoundException {
79	    for (int value = 0; value < finderPatterns.length; value++) {
80	      if (patternMatchVariance(counters, finderPatterns[value], MAX_INDIVIDUAL_VARIANCE) <
81	          MAX_AVG_VARIANCE) {
82	        return value;
83	      }
84	    }
85	    throw NotFoundException.getNotFoundInstance();
86	  }
87	
88	  /**
89	   * @param array values to sum
90	   * @return sum of values
91	   * @deprecated call {@link MathUtils#sum(int[])}
92	   */
93	  @Deprecated
94	  protected static int count(int[] array) {
95	    return MathUtils.sum(array);
96	  }
97	
98	  protected static void increment(int[] array, float[] errors) {
99	    int index = 0;
100	    float biggestError = errors[0];
101	    for (int i = 1; i < array.length; i++) {
102	      if (errors[i] > biggestError) {
103	        biggestError = errors[i];
104	        index = i;
105	      }
106	    }
107	    array[index]++;
108	  }
109	
110	  protected static void decrement(int[] array, float[] errors) {
111	    int index = 0;
112	    float biggestError = errors[0];
113	    for (int i = 1; i < array.length; i++) {
114	      if (errors[i] < biggestError) {
115	        biggestError = errors[i];
116	        index = i;
117	      }
118	    }
119	    array[index]--;
120	  }
121	
122	  protected static boolean isFinderPattern(int[] counters) {
123	    int firstTwoSum = counters[0] + counters[1];
124	    int sum = firstTwoSum + counters[2] + counters[3];
125	    float ratio = firstTwoSum / (float) sum;
126	    if (ratio >= MIN_FINDER_PATTERN_RATIO && ratio <= MAX_FINDER_PATTERN_RATIO) {
127	      // passes ratio test in spec, but see if the counts are unreasonable
128	      int minCounter = Integer.MAX_VALUE;
129	      int maxCounter = Integer.MIN_VALUE;
130	      for (int counter : counters) {
131	        if (counter > maxCounter) {
132	          maxCounter = counter;
133	        }
134	        if (counter < minCounter) {
135	          minCounter = counter;
136	        }
137	      }
138	      return maxCounter < 10 * minCounter;
139	    }
140	    return false;
141	  }
142	}
