27	import com.google.zxing.common.detector.MathUtils;
28	
29	import java.util.Arrays;
30	import java.util.ArrayList;
31	import java.util.Collection;
32	import java.util.List;
33	import java.util.Map;
34	
35	/**
36	 * Decodes RSS-14, including truncated and stacked variants. See ISO/IEC 24724:2006.
37	 */
38	public final class RSS14Reader extends AbstractRSSReader {
39	
40	  private static final int[] OUTSIDE_EVEN_TOTAL_SUBSET = {1,10,34,70,126};
41	  private static final int[] INSIDE_ODD_TOTAL_SUBSET = {4,20,48,81};
42	  private static final int[] OUTSIDE_GSUM = {0,161,961,2015,2715};
43	  private static final int[] INSIDE_GSUM = {0,336,1036,1516};
44	  private static final int[] OUTSIDE_ODD_WIDEST = {8,6,4,3,1};
45	  private static final int[] INSIDE_ODD_WIDEST = {2,4,6,8};
46	
47	  private static final int[][] FINDER_PATTERNS = {
48	      {3,8,2,1},
49	      {3,5,5,1},
50	      {3,3,7,1},
51	      {3,1,9,1},
52	      {2,7,4,1},
53	      {2,5,6,1},
54	      {2,3,8,1},
55	      {1,5,7,1},
56	      {1,3,9,1},
57	  };
58	
59	  private final List<Pair> possibleLeftPairs;
60	  private final List<Pair> possibleRightPairs;
61	
62	  public RSS14Reader() {
63	    possibleLeftPairs = new ArrayList<>();
64	    possibleRightPairs = new ArrayList<>();
65	  }
66	
67	  @Override
68	  public Result decodeRow(int rowNumber,
69	                          BitArray row,
70	                          Map<DecodeHintType,?> hints) throws NotFoundException {
71	    Pair leftPair = decodePair(row, false, rowNumber, hints);
72	    addOrTally(possibleLeftPairs, leftPair);
73	    row.reverse();
74	    Pair rightPair = decodePair(row, true, rowNumber, hints);
75	    addOrTally(possibleRightPairs, rightPair);
76	    row.reverse();
77	    for (Pair left : possibleLeftPairs) {
78	      if (left.getCount() > 1) {
79	        for (Pair right : possibleRightPairs) {
80	          if (right.getCount() > 1 && checkChecksum(left, right)) {
81	            return constructResult(left, right);
82	          }
83	        }
84	      }
85	    }
86	    throw NotFoundException.getNotFoundInstance();
87	  }
88	
89	  private static void addOrTally(Collection<Pair> possiblePairs, Pair pair) {
90	    if (pair == null) {
91	      return;
92	    }
93	    boolean found = false;
94	    for (Pair other : possiblePairs) {
95	      if (other.getValue() == pair.getValue()) {
96	        other.incrementCount();
97	        found = true;
98	        break;
99	      }
100	    }
101	    if (!found) {
102	      possiblePairs.add(pair);
103	    }
104	  }
105	
106	  @Override
107	  public void reset() {
108	    possibleLeftPairs.clear();
109	    possibleRightPairs.clear();
110	  }
111	
112	  private static Result constructResult(Pair leftPair, Pair rightPair) {
113	    long symbolValue = 4537077L * leftPair.getValue() + rightPair.getValue();
114	    String text = String.valueOf(symbolValue);
115	
116	    StringBuilder buffer = new StringBuilder(14);
117	    for (int i = 13 - text.length(); i > 0; i--) {
118	      buffer.append('0');
119	    }
120	    buffer.append(text);
121	
122	    int checkDigit = 0;
123	    for (int i = 0; i < 13; i++) {
124	      int digit = buffer.charAt(i) - '0';
125	      checkDigit += (i & 0x01) == 0 ? 3 * digit : digit;
126	    }
127	    checkDigit = 10 - (checkDigit % 10);
128	    if (checkDigit == 10) {
129	      checkDigit = 0;
130	    }
131	    buffer.append(checkDigit);
132	
133	    ResultPoint[] leftPoints = leftPair.getFinderPattern().getResultPoints();
134	    ResultPoint[] rightPoints = rightPair.getFinderPattern().getResultPoints();
135	    Result result = new Result(
136	        buffer.toString(),
137	        null,
138	        new ResultPoint[] { leftPoints[0], leftPoints[1], rightPoints[0], rightPoints[1], },
139	        BarcodeFormat.RSS_14);
140	    result.putMetadata(ResultMetadataType.SYMBOLOGY_IDENTIFIER, "]e0");
141	    return result;
142	  }
143	
144	  private static boolean checkChecksum(Pair leftPair, Pair rightPair) {
145	    int checkValue = (leftPair.getChecksumPortion() + 16 * rightPair.getChecksumPortion()) % 79;
146	    int targetCheckValue =
147	        9 * leftPair.getFinderPattern().getValue() + rightPair.getFinderPattern().getValue();
148	    if (targetCheckValue > 72) {
149	      targetCheckValue--;
150	    }
151	    if (targetCheckValue > 8) {
152	      targetCheckValue--;
153	    }
154	    return checkValue == targetCheckValue;
155	  }
156	
157	  private Pair decodePair(BitArray row, boolean right, int rowNumber, Map<DecodeHintType,?> hints) {
158	    try {
159	      int[] startEnd = findFinderPattern(row, right);
160	      FinderPattern pattern = parseFoundFinderPattern(row, rowNumber, right, startEnd);
161	
162	      ResultPointCallback resultPointCallback = hints == null ? null :
163	          (ResultPointCallback) hints.get(DecodeHintType.NEED_RESULT_POINT_CALLBACK);
164	
165	      if (resultPointCallback != null) {
166	        startEnd = pattern.getStartEnd();
167	        float center = (startEnd[0] + startEnd[1] - 1) / 2.0f;
168	        if (right) {
169	          // row is actually reversed
170	          center = row.getSize() - 1 - center;
171	        }
172	        resultPointCallback.foundPossibleResultPoint(new ResultPoint(center, rowNumber));
173	      }
174	
175	      DataCharacter outside = decodeDataCharacter(row, pattern, true);
176	      DataCharacter inside = decodeDataCharacter(row, pattern, false);
177	      return new Pair(1597 * outside.getValue() + inside.getValue(),
178	                      outside.getChecksumPortion() + 4 * inside.getChecksumPortion(),
179	                      pattern);
180	    } catch (NotFoundException ignored) {
181	      return null;
182	    }
183	  }
184	
185	  private DataCharacter decodeDataCharacter(BitArray row, FinderPattern pattern, boolean outsideChar)
186	      throws NotFoundException {
187	
188	    int[] counters = getDataCharacterCounters();
189	    Arrays.fill(counters, 0);
190	
191	    if (outsideChar) {
192	      recordPatternInReverse(row, pattern.getStartEnd()[0], counters);
193	    } else {
194	      recordPattern(row, pattern.getStartEnd()[1], counters);
195	      // reverse it
196	      for (int i = 0, j = counters.length - 1; i < j; i++, j--) {
197	        int temp = counters[i];
198	        counters[i] = counters[j];
199	        counters[j] = temp;
200	      }
201	    }
202	
203	    int numModules = outsideChar ? 16 : 15;
204	    float elementWidth = MathUtils.sum(counters) / (float) numModules;
205	
206	    int[] oddCounts = this.getOddCounts();
207	    int[] evenCounts = this.getEvenCounts();
208	    float[] oddRoundingErrors = this.getOddRoundingErrors();
209	    float[] evenRoundingErrors = this.getEvenRoundingErrors();
210	
211	    for (int i = 0; i < counters.length; i++) {
212	      float value = counters[i] / elementWidth;
213	      int count = (int) (value + 0.5f); // Round
214	      if (count < 1) {
215	        count = 1;
216	      } else if (count > 8) {
217	        count = 8;
218	      }
219	      int offset = i / 2;
220	      if ((i & 0x01) == 0) {
221	        oddCounts[offset] = count;
222	        oddRoundingErrors[offset] = value - count;
223	      } else {
224	        evenCounts[offset] = count;
225	        evenRoundingErrors[offset] = value - count;
226	      }
227	    }
228	
229	    adjustOddEvenCounts(outsideChar, numModules);
230	
231	    int oddSum = 0;
232	    int oddChecksumPortion = 0;
233	    for (int i = oddCounts.length - 1; i >= 0; i--) {
234	      oddChecksumPortion *= 9;
235	      oddChecksumPortion += oddCounts[i];
236	      oddSum += oddCounts[i];
237	    }
238	    int evenChecksumPortion = 0;
239	    int evenSum = 0;
240	    for (int i = evenCounts.length - 1; i >= 0; i--) {
241	      evenChecksumPortion *= 9;
242	      evenChecksumPortion += evenCounts[i];
243	      evenSum += evenCounts[i];
244	    }
245	    int checksumPortion = oddChecksumPortion + 3 * evenChecksumPortion;
246	
247	    if (outsideChar) {
248	      if ((oddSum & 0x01) != 0 || oddSum > 12 || oddSum < 4) {
249	        throw NotFoundException.getNotFoundInstance();
250	      }
251	      int group = (12 - oddSum) / 2;
252	      int oddWidest = OUTSIDE_ODD_WIDEST[group];
253	      int evenWidest = 9 - oddWidest;
254	      int vOdd = RSSUtils.getRSSvalue(oddCounts, oddWidest, false);
255	      int vEven = RSSUtils.getRSSvalue(evenCounts, evenWidest, true);
256	      int tEven = OUTSIDE_EVEN_TOTAL_SUBSET[group];
257	      int gSum = OUTSIDE_GSUM[group];
258	      return new DataCharacter(vOdd * tEven + vEven + gSum, checksumPortion);
259	    } else {
260	      if ((evenSum & 0x01) != 0 || evenSum > 10 || evenSum < 4) {
261	        throw NotFoundException.getNotFoundInstance();
262	      }
263	      int group = (10 - evenSum) / 2;
264	      int oddWidest = INSIDE_ODD_WIDEST[group];
265	      int evenWidest = 9 - oddWidest;
266	      int vOdd = RSSUtils.getRSSvalue(oddCounts, oddWidest, true);
267	      int vEven = RSSUtils.getRSSvalue(evenCounts, evenWidest, false);
268	      int tOdd = INSIDE_ODD_TOTAL_SUBSET[group];
269	      int gSum = INSIDE_GSUM[group];
270	      return new DataCharacter(vEven * tOdd + vOdd + gSum, checksumPortion);
271	    }
272	
273	  }
274	
275	  private int[] findFinderPattern(BitArray row, boolean rightFinderPattern)
276	      throws NotFoundException {
277	
278	    int[] counters = getDecodeFinderCounters();
279	    counters[0] = 0;
280	    counters[1] = 0;
281	    counters[2] = 0;
282	    counters[3] = 0;
283	
284	    int width = row.getSize();
285	    boolean isWhite = false;
286	    int rowOffset = 0;
287	    while (rowOffset < width) {
288	      isWhite = !row.get(rowOffset);
289	      if (rightFinderPattern == isWhite) {
290	        // Will encounter white first when searching for right finder pattern
291	        break;
292	      }
293	      rowOffset++;
294	    }
295	
296	    int counterPosition = 0;
297	    int patternStart = rowOffset;
298	    for (int x = rowOffset; x < width; x++) {
299	      if (row.get(x) != isWhite) {
300	        counters[counterPosition]++;
301	      } else {
302	        if (counterPosition == 3) {
303	          if (isFinderPattern(counters)) {
304	            return new int[]{patternStart, x};
305	          }
306	          patternStart += counters[0] + counters[1];
307	          counters[0] = counters[2];
308	          counters[1] = counters[3];
309	          counters[2] = 0;
310	          counters[3] = 0;
311	          counterPosition--;
312	        } else {
313	          counterPosition++;
314	        }
315	        counters[counterPosition] = 1;
316	        isWhite = !isWhite;
317	      }
318	    }
319	    throw NotFoundException.getNotFoundInstance();
320	
321	  }
322	
323	  private FinderPattern parseFoundFinderPattern(BitArray row, int rowNumber, boolean right, int[] startEnd)
324	      throws NotFoundException {
325	    // Actually we found elements 2-5
326	    boolean firstIsBlack = row.get(startEnd[0]);
327	    int firstElementStart = startEnd[0] - 1;
328	    // Locate element 1
329	    while (firstElementStart >= 0 && firstIsBlack != row.get(firstElementStart)) {
330	      firstElementStart--;
331	    }
332	    firstElementStart++;
333	    int firstCounter = startEnd[0] - firstElementStart;
334	    // Make 'counters' hold 1-4
335	    int[] counters = getDecodeFinderCounters();
336	    System.arraycopy(counters, 0, counters, 1, counters.length - 1);
337	    counters[0] = firstCounter;
338	    int value = parseFinderValue(counters, FINDER_PATTERNS);
339	    int start = firstElementStart;
340	    int end = startEnd[1];
341	    if (right) {
342	      // row is actually reversed
343	      start = row.getSize() - 1 - start;
344	      end = row.getSize() - 1 - end;
345	    }
346	    return new FinderPattern(value, new int[] {firstElementStart, startEnd[1]}, start, end, rowNumber);
347	  }
348	
349	  private void adjustOddEvenCounts(boolean outsideChar, int numModules) throws NotFoundException {
350	
351	    int oddSum = MathUtils.sum(getOddCounts());
352	    int evenSum = MathUtils.sum(getEvenCounts());
353	
354	    boolean incrementOdd = false;
355	    boolean decrementOdd = false;
356	    boolean incrementEven = false;
357	    boolean decrementEven = false;
358	
359	    if (outsideChar) {
360	      if (oddSum > 12) {
361	        decrementOdd = true;
362	      } else if (oddSum < 4) {
363	        incrementOdd = true;
364	      }
365	      if (evenSum > 12) {
366	        decrementEven = true;
367	      } else if (evenSum < 4) {
368	        incrementEven = true;
369	      }
370	    } else {
371	      if (oddSum > 11) {
372	        decrementOdd = true;
373	      } else if (oddSum < 5) {
374	        incrementOdd = true;
375	      }
376	      if (evenSum > 10) {
377	        decrementEven = true;
378	      } else if (evenSum < 4) {
379	        incrementEven = true;
380	      }
381	    }
382	
383	    int mismatch = oddSum + evenSum - numModules;
384	    boolean oddParityBad = (oddSum & 0x01) == (outsideChar ? 1 : 0);
385	    boolean evenParityBad = (evenSum & 0x01) == 1;
386	    /*if (mismatch == 2) {
387	      if (!(oddParityBad && evenParityBad)) {
388	        throw ReaderException.getInstance();
389	      }
390	      decrementOdd = true;
391	      decrementEven = true;
392	    } else if (mismatch == -2) {
393	      if (!(oddParityBad && evenParityBad)) {
394	        throw ReaderException.getInstance();
395	      }
396	      incrementOdd = true;
397	      incrementEven = true;
398	    } else */
399	    switch (mismatch) {
400	      case 1:
401	        if (oddParityBad) {
402	          if (evenParityBad) {
403	            throw NotFoundException.getNotFoundInstance();
404	          }
405	          decrementOdd = true;
406	        } else {
407	          if (!evenParityBad) {
408	            throw NotFoundException.getNotFoundInstance();
409	          }
410	          decrementEven = true;
411	        }
412	        break;
413	      case -1:
414	        if (oddParityBad) {
415	          if (evenParityBad) {
416	            throw NotFoundException.getNotFoundInstance();
417	          }
418	          incrementOdd = true;
419	        } else {
420	          if (!evenParityBad) {
421	            throw NotFoundException.getNotFoundInstance();
422	          }
423	          incrementEven = true;
424	        }
425	        break;
426	      case 0:
427	        if (oddParityBad) {
428	          if (!evenParityBad) {
429	            throw NotFoundException.getNotFoundInstance();
430	          }
431	          // Both bad
432	          if (oddSum < evenSum) {
433	            incrementOdd = true;
434	            decrementEven = true;
435	          } else {
436	            decrementOdd = true;
437	            incrementEven = true;
438	          }
439	        } else {
440	          if (evenParityBad) {
441	            throw NotFoundException.getNotFoundInstance();
442	          }
443	          // Nothing to do!
444	        }
445	        break;
446	      default:
447	        throw NotFoundException.getNotFoundInstance();
448	    }
449	
450	    if (incrementOdd) {
451	      if (decrementOdd) {
452	        throw NotFoundException.getNotFoundInstance();
453	      }
454	      increment(getOddCounts(), getOddRoundingErrors());
455	    }
456	    if (decrementOdd) {
457	      decrement(getOddCounts(), getOddRoundingErrors());
458	    }
459	    if (incrementEven) {
460	      if (decrementEven) {
461	        throw NotFoundException.getNotFoundInstance();
462	      }
463	      increment(getEvenCounts(), getOddRoundingErrors());
464	    }
465	    if (decrementEven) {
466	      decrement(getEvenCounts(), getEvenRoundingErrors());
467	    }
468	
469	  }
470	
471	}
