32	/**
33	 * <p>Decodes Code 39 barcodes. Supports "Full ASCII Code 39" if USE_CODE_39_EXTENDED_MODE is set.</p>
34	 *
35	 * @author Sean Owen
36	 * @see Code93Reader
37	 */
38	public final class Code39Reader extends OneDReader {
39	
40	  static final String ALPHABET_STRING = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ-. $/+%";
41	
42	  /**
43	   * These represent the encodings of characters, as patterns of wide and narrow bars.
44	   * The 9 least-significant bits of each int correspond to the pattern of wide and narrow,
45	   * with 1s representing "wide" and 0s representing narrow.
46	   */
47	  static final int[] CHARACTER_ENCODINGS = {
48	      0x034, 0x121, 0x061, 0x160, 0x031, 0x130, 0x070, 0x025, 0x124, 0x064, // 0-9
49	      0x109, 0x049, 0x148, 0x019, 0x118, 0x058, 0x00D, 0x10C, 0x04C, 0x01C, // A-J
50	      0x103, 0x043, 0x142, 0x013, 0x112, 0x052, 0x007, 0x106, 0x046, 0x016, // K-T
51	      0x181, 0x0C1, 0x1C0, 0x091, 0x190, 0x0D0, 0x085, 0x184, 0x0C4, 0x0A8, // U-$
52	      0x0A2, 0x08A, 0x02A // /-%
53	  };
54	
55	  static final int ASTERISK_ENCODING = 0x094;
56	
57	  private final boolean usingCheckDigit;
58	  private final boolean extendedMode;
59	  private final StringBuilder decodeRowResult;
60	  private final int[] counters;
61	
62	  /**
63	   * Creates a reader that assumes all encoded data is data, and does not treat the final
64	   * character as a check digit. It will not decoded "extended Code 39" sequences.
65	   */
66	  public Code39Reader() {
67	    this(false);
68	  }
69	
70	  /**
71	   * Creates a reader that can be configured to check the last character as a check digit.
72	   * It will not decoded "extended Code 39" sequences.
73	   *
74	   * @param usingCheckDigit if true, treat the last data character as a check digit, not
75	   * data, and verify that the checksum passes.
76	   */
77	  public Code39Reader(boolean usingCheckDigit) {
78	    this(usingCheckDigit, false);
79	  }
80	
81	  /**
82	   * Creates a reader that can be configured to check the last character as a check digit,
83	   * or optionally attempt to decode "extended Code 39" sequences that are used to encode
84	   * the full ASCII character set.
85	   *
86	   * @param usingCheckDigit if true, treat the last data character as a check digit, not
87	   * data, and verify that the checksum passes.
88	   * @param extendedMode if true, will attempt to decode extended Code 39 sequences in the
89	   * text.
90	   */
91	  public Code39Reader(boolean usingCheckDigit, boolean extendedMode) {
92	    this.usingCheckDigit = usingCheckDigit;
93	    this.extendedMode = extendedMode;
94	    decodeRowResult = new StringBuilder(20);
95	    counters = new int[9];
96	  }
97	
98	  @Override
99	  public Result decodeRow(int rowNumber, BitArray row, Map<DecodeHintType,?> hints)
100	      throws NotFoundException, ChecksumException, FormatException {
101	
102	    int[] theCounters = counters;
103	    Arrays.fill(theCounters, 0);
104	    StringBuilder result = decodeRowResult;
105	    result.setLength(0);
106	
107	    int[] start = findAsteriskPattern(row, theCounters);
108	    // Read off white space
109	    int nextStart = row.getNextSet(start[1]);
110	    int end = row.getSize();
111	
112	    char decodedChar;
113	    int lastStart;
114	    do {
115	      recordPattern(row, nextStart, theCounters);
116	      int pattern = toNarrowWidePattern(theCounters);
117	      if (pattern < 0) {
118	        throw NotFoundException.getNotFoundInstance();
119	      }
120	      decodedChar = patternToChar(pattern);
121	      result.append(decodedChar);
122	      lastStart = nextStart;
123	      for (int counter : theCounters) {
124	        nextStart += counter;
125	      }
126	      // Read off white space
127	      nextStart = row.getNextSet(nextStart);
128	    } while (decodedChar != '*');
129	    result.setLength(result.length() - 1); // remove asterisk
130	
131	    // Look for whitespace after pattern:
132	    int lastPatternSize = 0;
133	    for (int counter : theCounters) {
134	      lastPatternSize += counter;
135	    }
136	    int whiteSpaceAfterEnd = nextStart - lastStart - lastPatternSize;
137	    // If 50% of last pattern size, following last pattern, is not whitespace, fail
138	    // (but if it's whitespace to the very end of the image, that's OK)
139	    if (nextStart != end && (whiteSpaceAfterEnd * 2) < lastPatternSize) {
140	      throw NotFoundException.getNotFoundInstance();
141	    }
142	
143	    if (usingCheckDigit) {
144	      if (result.length() == 0) {
145	        // false positive -- a symbol with no payload cannot carry a check digit
146	        throw NotFoundException.getNotFoundInstance();
147	      }
148	      int max = result.length() - 1;
149	      int total = 0;
150	      for (int i = 0; i < max; i++) {
151	        total += ALPHABET_STRING.indexOf(decodeRowResult.charAt(i));
152	      }
153	      if (result.charAt(max) != ALPHABET_STRING.charAt(total % 43)) {
154	        throw ChecksumException.getChecksumInstance();
155	      }
156	      result.setLength(max);
157	    }
158	
159	    if (result.length() == 0) {
160	      // false positive
161	      throw NotFoundException.getNotFoundInstance();
162	    }
163	
164	    String resultString;
165	    if (extendedMode) {
166	      resultString = decodeExtended(result);
167	    } else {
168	      resultString = result.toString();
169	    }
170	
171	    float left = (start[1] + start[0]) / 2.0f;
172	    float right = lastStart + lastPatternSize / 2.0f;
173	
174	    Result resultObject = new Result(
175	        resultString,
176	        null,
177	        new ResultPoint[]{
178	            new ResultPoint(left, rowNumber),
179	            new ResultPoint(right, rowNumber)},
180	        BarcodeFormat.CODE_39);
181	    resultObject.putMetadata(ResultMetadataType.SYMBOLOGY_IDENTIFIER, "]A0");
182	    return resultObject;
183	  }
184	
185	  private static int[] findAsteriskPattern(BitArray row, int[] counters) throws NotFoundException {
186	    int width = row.getSize();
187	    int rowOffset = row.getNextSet(0);
188	
189	    int counterPosition = 0;
190	    int patternStart = rowOffset;
191	    boolean isWhite = false;
192	    int patternLength = counters.length;
193	
194	    for (int i = rowOffset; i < width; i++) {
195	      if (row.get(i) != isWhite) {
196	        counters[counterPosition]++;
197	      } else {
198	        if (counterPosition == patternLength - 1) {
199	          // Look for whitespace before start pattern, >= 50% of width of start pattern
200	          if (toNarrowWidePattern(counters) == ASTERISK_ENCODING &&
201	              row.isRange(Math.max(0, patternStart - ((i - patternStart) / 2)), patternStart, false)) {
202	            return new int[]{patternStart, i};
203	          }
204	          patternStart += counters[0] + counters[1];
205	          System.arraycopy(counters, 2, counters, 0, counterPosition - 1);
206	          counters[counterPosition - 1] = 0;
207	          counters[counterPosition] = 0;
208	          counterPosition--;
209	        } else {
210	          counterPosition++;
211	        }
212	        counters[counterPosition] = 1;
213	        isWhite = !isWhite;
214	      }
215	    }
216	    throw NotFoundException.getNotFoundInstance();
217	  }
218	
219	  // For efficiency, returns -1 on failure. Not throwing here saved as many as 700 exceptions
220	  // per image when using some of our blackbox images.
221	  private static int toNarrowWidePattern(int[] counters) {
222	    int numCounters = counters.length;
223	    int maxNarrowCounter = 0;
224	    int wideCounters;
225	    do {
226	      int minCounter = Integer.MAX_VALUE;
227	      for (int counter : counters) {
228	        if (counter < minCounter && counter > maxNarrowCounter) {
229	          minCounter = counter;
230	        }
231	      }
232	      maxNarrowCounter = minCounter;
233	      wideCounters = 0;
234	      int totalWideCountersWidth = 0;
235	      int pattern = 0;
236	      for (int i = 0; i < numCounters; i++) {
237	        int counter = counters[i];
238	        if (counter > maxNarrowCounter) {
239	          pattern |= 1 << (numCounters - 1 - i);
240	          wideCounters++;
241	          totalWideCountersWidth += counter;
242	        }
243	      }
244	      if (wideCounters == 3) {
245	        // Found 3 wide counters, but are they close enough in width?
246	        // We can perform a cheap, conservative check to see if any individual
247	        // counter is more than 1.5 times the average:
248	        for (int i = 0; i < numCounters && wideCounters > 0; i++) {
249	          int counter = counters[i];
250	          if (counter > maxNarrowCounter) {
251	            wideCounters--;
252	            // totalWideCountersWidth = 3 * average, so this checks if counter >= 3/2 * average
253	            if ((counter * 2) >= totalWideCountersWidth) {
254	              return -1;
255	            }
256	          }
257	        }
258	        return pattern;
259	      }
260	    } while (wideCounters > 3);
261	    return -1;
262	  }
263	
264	  private static char patternToChar(int pattern) throws NotFoundException {
265	    for (int i = 0; i < CHARACTER_ENCODINGS.length; i++) {
266	      if (CHARACTER_ENCODINGS[i] == pattern) {
267	        return ALPHABET_STRING.charAt(i);
268	      }
269	    }
270	    if (pattern == ASTERISK_ENCODING) {
271	      return '*';
272	    }
273	    throw NotFoundException.getNotFoundInstance();
274	  }
275	
276	  private static String decodeExtended(CharSequence encoded) throws FormatException {
277	    int length = encoded.length();
278	    StringBuilder decoded = new StringBuilder(length);
279	    for (int i = 0; i < length; i++) {
280	      char c = encoded.charAt(i);
281	      if (c == '+' || c == '$' || c == '%' || c == '/') {
282	        if (i >= length - 1) {
283	          throw FormatException.getFormatInstance();
284	        }
285	        char next = encoded.charAt(i + 1);
286	        char decodedChar = '\0';
287	        switch (c) {
288	          case '+':
289	            // +A to +Z map to a to z
290	            if (next >= 'A' && next <= 'Z') {
291	              decodedChar = (char) (next + 32);
292	            } else {
293	              throw FormatException.getFormatInstance();
294	            }
295	            break;
296	          case '$':
297	            // $A to $Z map to control codes SH to SB
298	            if (next >= 'A' && next <= 'Z') {
299	              decodedChar = (char) (next - 64);
300	            } else {
301	              throw FormatException.getFormatInstance();
302	            }
303	            break;
304	          case '%':
305	            // %A to %E map to control codes ESC to US
306	            if (next >= 'A' && next <= 'E') {
307	              decodedChar = (char) (next - 38);
308	            } else if (next >= 'F' && next <= 'J') {
309	              decodedChar = (char) (next - 11);
310	            } else if (next >= 'K' && next <= 'O') {
311	              decodedChar = (char) (next + 16);
312	            } else if (next >= 'P' && next <= 'T') {
313	              decodedChar = (char) (next + 43);
314	            } else if (next == 'U') {
315	              decodedChar = (char) 0;
316	            } else if (next == 'V') {
317	              decodedChar = '@';
318	            } else if (next == 'W') {
319	              decodedChar = '`';
320	            } else if (next == 'X' || next == 'Y' || next == 'Z') {
321	              decodedChar = (char) 127;
322	            } else {
323	              throw FormatException.getFormatInstance();
324	            }
325	            break;
326	          case '/':
327	            // /A to /O map to ! to , and /Z maps to :
328	            if (next >= 'A' && next <= 'O') {
329	              decodedChar = (char) (next - 32);
330	            } else if (next == 'Z') {
331	              decodedChar = ':';
332	            } else {
333	              throw FormatException.getFormatInstance();
334	            }
335	            break;
336	        }
337	        decoded.append(decodedChar);
338	        // bump up i again since we read two characters
339	        i++;
340	      } else {
341	        decoded.append(c);
342	      }
343	    }
344	    return decoded.toString();
345	  }
