32	/**
33	 * <p>Decodes Code 93 barcodes.</p>
34	 *
35	 * @author Sean Owen
36	 * @see Code39Reader
37	 */
38	public final class Code93Reader extends OneDReader {
39	
40	  // Note that 'abcd' are dummy characters in place of control characters.
41	  static final String ALPHABET_STRING = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ-. $/+%abcd*";
42	  private static final char[] ALPHABET = ALPHABET_STRING.toCharArray();
43	
44	  /**
45	   * These represent the encodings of characters, as patterns of wide and narrow bars.
46	   * The 9 least-significant bits of each int correspond to the pattern of wide and narrow.
47	   */
48	  static final int[] CHARACTER_ENCODINGS = {
49	      0x114, 0x148, 0x144, 0x142, 0x128, 0x124, 0x122, 0x150, 0x112, 0x10A, // 0-9
50	      0x1A8, 0x1A4, 0x1A2, 0x194, 0x192, 0x18A, 0x168, 0x164, 0x162, 0x134, // A-J
51	      0x11A, 0x158, 0x14C, 0x146, 0x12C, 0x116, 0x1B4, 0x1B2, 0x1AC, 0x1A6, // K-T
52	      0x196, 0x19A, 0x16C, 0x166, 0x136, 0x13A, // U-Z
53	      0x12E, 0x1D4, 0x1D2, 0x1CA, 0x16E, 0x176, 0x1AE, // - - %
54	      0x126, 0x1DA, 0x1D6, 0x132, 0x15E, // Control chars? $-*
55	  };
56	  static final int ASTERISK_ENCODING = CHARACTER_ENCODINGS[47];
57	
58	  private final StringBuilder decodeRowResult;
59	  private final int[] counters;
60	
61	  public Code93Reader() {
62	    decodeRowResult = new StringBuilder(20);
63	    counters = new int[6];
64	  }
65	
66	  @Override
67	  public Result decodeRow(int rowNumber, BitArray row, Map<DecodeHintType,?> hints)
68	      throws NotFoundException, ChecksumException, FormatException {
69	
70	    int[] start = findAsteriskPattern(row);
71	    // Read off white space
72	    int nextStart = row.getNextSet(start[1]);
73	    int end = row.getSize();
74	
75	    int[] theCounters = counters;
76	    Arrays.fill(theCounters, 0);
77	    StringBuilder result = decodeRowResult;
78	    result.setLength(0);
79	
80	    char decodedChar;
81	    int lastStart;
82	    do {
83	      recordPattern(row, nextStart, theCounters);
84	      int pattern = toPattern(theCounters);
85	      if (pattern < 0) {
86	        throw NotFoundException.getNotFoundInstance();
87	      }
88	      decodedChar = patternToChar(pattern);
89	      result.append(decodedChar);
90	      lastStart = nextStart;
91	      for (int counter : theCounters) {
92	        nextStart += counter;
93	      }
94	      // Read off white space
95	      nextStart = row.getNextSet(nextStart);
96	    } while (decodedChar != '*');
97	    result.deleteCharAt(result.length() - 1); // remove asterisk
98	
99	    int lastPatternSize = 0;
100	    for (int counter : theCounters) {
101	      lastPatternSize += counter;
102	    }
103	
104	    // Should be at least one more black module
105	    if (nextStart == end || !row.get(nextStart)) {
106	      throw NotFoundException.getNotFoundInstance();
107	    }
108	
109	    if (result.length() < 2) {
110	      // false positive -- need at least 2 checksum digits
111	      throw NotFoundException.getNotFoundInstance();
112	    }
113	
114	    checkChecksums(result);
115	    // Remove checksum digits
116	    result.setLength(result.length() - 2);
117	
118	    String resultString = decodeExtended(result);
119	
120	    float left = (start[1] + start[0]) / 2.0f;
121	    float right = lastStart + lastPatternSize / 2.0f;
122	
123	    Result resultObject = new Result(
124	        resultString,
125	        null,
126	        new ResultPoint[]{
127	            new ResultPoint(left, rowNumber),
128	            new ResultPoint(right, rowNumber)},
129	        BarcodeFormat.CODE_93);
130	    resultObject.putMetadata(ResultMetadataType.SYMBOLOGY_IDENTIFIER, "]G0");
131	    return resultObject;
132	  }
133	
134	  private int[] findAsteriskPattern(BitArray row) throws NotFoundException {
135	    int width = row.getSize();
136	    int rowOffset = row.getNextSet(0);
137	
138	    Arrays.fill(counters, 0);
139	    int[] theCounters = counters;
140	    int patternStart = rowOffset;
141	    boolean isWhite = false;
142	    int patternLength = theCounters.length;
143	
144	    int counterPosition = 0;
145	    for (int i = rowOffset; i < width; i++) {
146	      if (row.get(i) != isWhite) {
147	        theCounters[counterPosition]++;
148	      } else {
149	        if (counterPosition == patternLength - 1) {
150	          if (toPattern(theCounters) == ASTERISK_ENCODING) {
151	            return new int[]{patternStart, i};
152	          }
153	          patternStart += theCounters[0] + theCounters[1];
154	          System.arraycopy(theCounters, 2, theCounters, 0, counterPosition - 1);
155	          theCounters[counterPosition - 1] = 0;
156	          theCounters[counterPosition] = 0;
157	          counterPosition--;
158	        } else {
159	          counterPosition++;
160	        }
161	        theCounters[counterPosition] = 1;
162	        isWhite = !isWhite;
163	      }
164	    }
165	    throw NotFoundException.getNotFoundInstance();
166	  }
167	
168	  private static int toPattern(int[] counters) {
169	    int sum = 0;
170	    for (int counter : counters) {
171	      sum += counter;
172	    }
173	    int pattern = 0;
174	    int max = counters.length;
175	    for (int i = 0; i < max; i++) {
176	      int scaled = Math.round(counters[i] * 9.0f / sum);
177	      if (scaled < 1 || scaled > 4) {
178	        return -1;
179	      }
180	      if ((i & 0x01) == 0) {
181	        for (int j = 0; j < scaled; j++) {
182	          pattern = (pattern << 1) | 0x01;
183	        }
184	      } else {
185	        pattern <<= scaled;
186	      }
187	    }
188	    return pattern;
189	  }
190	
191	  private static char patternToChar(int pattern) throws NotFoundException {
192	    for (int i = 0; i < CHARACTER_ENCODINGS.length; i++) {
193	      if (CHARACTER_ENCODINGS[i] == pattern) {
194	        return ALPHABET[i];
195	      }
196	    }
197	    throw NotFoundException.getNotFoundInstance();
198	  }
