200	  private static String decodeExtended(CharSequence encoded) throws FormatException {
201	    int length = encoded.length();
202	    StringBuilder decoded = new StringBuilder(length);
203	    for (int i = 0; i < length; i++) {
204	      char c = encoded.charAt(i);
205	      if (c >= 'a' && c <= 'd') {
206	        if (i >= length - 1) {
207	          throw FormatException.getFormatInstance();
208	        }
209	        char next = encoded.charAt(i + 1);
210	        char decodedChar = '\0';
211	        switch (c) {
212	          case 'd':
213	            // +A to +Z map to a to z
214	            if (next >= 'A' && next <= 'Z') {
215	              decodedChar = (char) (next + 32);
216	            } else {
217	              throw FormatException.getFormatInstance();
218	            }
219	            break;
220	          case 'a':
221	            // $A to $Z map to control codes SH to SB
222	            if (next >= 'A' && next <= 'Z') {
223	              decodedChar = (char) (next - 64);
224	            } else {
225	              throw FormatException.getFormatInstance();
226	            }
227	            break;
228	          case 'b':
229	            if (next >= 'A' && next <= 'E') {
230	              // %A to %E map to control codes ESC to USep
231	              decodedChar = (char) (next - 38);
232	            } else if (next >= 'F' && next <= 'J') {
233	              // %F to %J map to ; < = > ?
234	              decodedChar = (char) (next - 11);
235	            } else if (next >= 'K' && next <= 'O') {
236	              // %K to %O map to [ \ ] ^ _
237	              decodedChar = (char) (next + 16);
238	            } else if (next >= 'P' && next <= 'T') {
239	              // %P to %T map to { | } ~ DEL
240	              decodedChar = (char) (next + 43);
241	            } else if (next == 'U') {
242	              // %U map to NUL
243	              decodedChar = '\0';
244	            } else if (next == 'V') {
245	              // %V map to @
246	              decodedChar = '@';
247	            } else if (next == 'W') {
248	              // %W map to `
249	              decodedChar = '`';
250	            } else if (next >= 'X' && next <= 'Z') {
251	              // %X to %Z all map to DEL (127)
252	              decodedChar = 127;
253	            } else {
254	              throw FormatException.getFormatInstance();
255	            }
256	            break;
257	          case 'c':
258	            // /A to /O map to ! to , and /Z maps to :
259	            if (next >= 'A' && next <= 'O') {
260	              decodedChar = (char) (next - 32);
261	            } else if (next == 'Z') {
262	              decodedChar = ':';
263	            } else {
264	              throw FormatException.getFormatInstance();
265	            }
266	            break;
267	        }
268	        decoded.append(decodedChar);
269	        // bump up i again since we read two characters
270	        i++;
271	      } else {
272	        decoded.append(c);
273	      }
274	    }
275	    return decoded.toString();
276	  }
277	
278	  private static void checkChecksums(CharSequence result) throws ChecksumException {
279	    int length = result.length();
280	    checkOneChecksum(result, length - 2, 20);
281	    checkOneChecksum(result, length - 1, 15);
282	  }
283	
284	  private static void checkOneChecksum(CharSequence result, int checkPosition, int weightMax)
285	      throws ChecksumException {
286	    int weight = 1;
287	    int total = 0;
288	    for (int i = checkPosition - 1; i >= 0; i--) {
289	      total += weight * ALPHABET_STRING.indexOf(result.charAt(i));
290	      if (++weight > weightMax) {
291	        weight = 1;
292	      }
293	    }
294	    if (result.charAt(checkPosition) != ALPHABET[total % 47]) {
295	      throw ChecksumException.getChecksumInstance();
296	    }
297	  }
298	
