35	/**
36	 * <p>The main class which implements Aztec Code decoding -- as opposed to locating and extracting
37	 * the Aztec Code from an image.</p>
38	 *
39	 * @author David Olivier
40	 */
41	public final class Decoder {
42	
43	  private enum Table {
44	    UPPER,
45	    LOWER,
46	    MIXED,
47	    DIGIT,
48	    PUNCT,
