81	  public DecoderResult decode(AztecDetectorResult detectorResult) throws FormatException {
82	    ddata = detectorResult;
83	    BitMatrix matrix = detectorResult.getBits();
84	    boolean[] rawbits = extractBits(matrix);
85	    CorrectedBitsResult correctedBits = correctBits(rawbits);
86	    byte[] rawBytes = convertBoolArrayToByteArray(correctedBits.correctBits);
87	    String result = getEncodedData(correctedBits.correctBits);
88	    DecoderResult decoderResult =
89	        new DecoderResult(rawBytes, result, null, String.format(Locale.ROOT, "%d%%", correctedBits.ecLevel));
90	    decoderResult.setNumBits(correctedBits.correctBits.length);
91	    decoderResult.setErrorsCorrected(correctedBits.errorsCorrected);
92	    return decoderResult;
93	  }
