100	  /**
101	   * Gets the string encoded in the aztec code bits
102	   *
103	   * @return the decoded string
104	   */
105	  private static String getEncodedData(boolean[] correctedBits) throws FormatException {
106	    int endIndex = correctedBits.length;
107	    Table latchTable = Table.UPPER; // table most recently latched to
108	    Table shiftTable = Table.UPPER; // table to use for the next read
109	
110	    // Final decoded string result
111	    // (correctedBits-5) / 4 is an upper bound on the size (all-digit result)
112	    StringBuilder result = new StringBuilder(Math.max(0, (correctedBits.length - 5) / 4));
113	
114	    // Intermediary buffer of decoded bytes, which is decoded into a string and flushed
115	    // when character encoding changes (ECI) or input ends.
116	    ByteArrayOutputStream decodedBytes = new ByteArrayOutputStream();
117	    Charset encoding = DEFAULT_ENCODING;
118	
119	    int index = 0;
120	    while (index < endIndex) {
121	      if (shiftTable == Table.BINARY) {
122	        if (endIndex - index < 5) {
123	          break;
124	        }
125	        int length = readCode(correctedBits, index, 5);
126	        index += 5;
127	        if (length == 0) {
128	          if (endIndex - index < 11) {
129	            break;
130	          }
131	          length = readCode(correctedBits, index, 11) + 31;
132	          index += 11;
133	        }
134	        for (int charCount = 0; charCount < length; charCount++) {
135	          if (endIndex - index < 8) {
136	            index = endIndex;  // Force outer loop to exit
137	            break;
138	          }
139	          int code = readCode(correctedBits, index, 8);
140	          decodedBytes.write((byte) code);
141	          index += 8;
142	        }
143	        // Go back to whatever mode we had been in
144	        shiftTable = latchTable;
145	      } else {
146	        int size = shiftTable == Table.DIGIT ? 4 : 5;
147	        if (endIndex - index < size) {
148	          break;
149	        }
150	        int code = readCode(correctedBits, index, size);
151	        index += size;
152	        String str = getCharacter(shiftTable, code);
153	        if ("FLG(n)".equals(str)) {
154	          if (endIndex - index < 3) {
155	            break;
156	          }
157	          int n = readCode(correctedBits, index, 3);
158	          index += 3;
159	          //  flush bytes, FLG changes state
160	          try {
161	            result.append(decodedBytes.toString(encoding.name()));
162	          } catch (UnsupportedEncodingException uee) {
163	            throw new IllegalStateException(uee);
164	          }
165	          decodedBytes.reset();
166	          switch (n) {
167	            case 0:
168	              result.append((char) 29);  // translate FNC1 as ASCII 29
169	              break;
170	            case 7:
171	              throw FormatException.getFormatInstance(); // FLG(7) is reserved and illegal
172	            default:
173	              // ECI is decimal integer encoded as 1-6 codes in DIGIT mode
174	              int eci = 0;
175	              if (endIndex - index < 4 * n) {
176	                break;
177	              }
178	              while (n-- > 0) {
179	                int nextDigit = readCode(correctedBits, index, 4);
180	                index += 4;
181	                if (nextDigit < 2 || nextDigit > 11) {
182	                  throw FormatException.getFormatInstance(); // Not a decimal digit
183	                }
184	                eci = eci * 10 + (nextDigit - 2);
185	              }
186	              CharacterSetECI charsetECI = CharacterSetECI.getCharacterSetECIByValue(eci);
187	              if (charsetECI == null) {
188	                throw FormatException.getFormatInstance();
189	              }
190	              encoding = charsetECI.getCharset();
191	          }
192	          // Go back to whatever mode we had been in
193	          shiftTable = latchTable;
194	        } else if (str.startsWith("CTRL_")) {
195	          // Table changes
196	          // ISO/IEC 24778:2008 prescribes ending a shift sequence in the mode from which it was invoked.
197	          // That's including when that mode is a shift.
198	          // Our test case dlusbs.png for issue #642 exercises that.
199	          latchTable = shiftTable;  // Latch the current mode, so as to return to Upper after U/S B/S
200	          shiftTable = getTable(str.charAt(5));
201	          if (str.charAt(6) == 'L') {
202	            latchTable = shiftTable;
203	          }
204	        } else {
205	          // Though stored as a table of strings for convenience, codes actually represent 1 or 2 *bytes*.
206	          byte[] b = str.getBytes(StandardCharsets.US_ASCII);
207	          decodedBytes.write(b, 0, b.length);
208	          // Go back to whatever mode we had been in
209	          shiftTable = latchTable;
210	        }
211	      }
212	    }
213	    try {
214	      result.append(decodedBytes.toString(encoding.name()));
215	    } catch (UnsupportedEncodingException uee) {
216	      // can't happen
217	      throw new IllegalStateException(uee);
218	    }
219	    return result.toString();
220	  }
221	
222	  /**
223	   * gets the table corresponding to the char passed
224	   */
225	  private static Table getTable(char t) {
226	    switch (t) {
227	      case 'L':
228	        return Table.LOWER;
229	      case 'P':
230	        return Table.PUNCT;
231	      case 'M':
232	        return Table.MIXED;
233	      case 'D':
234	        return Table.DIGIT;
235	      case 'B':
236	        return Table.BINARY;
237	      case 'U':
238	      default:
239	        return Table.UPPER;
240	    }
241	  }
242	
243	  /**
244	   * Gets the character (or string) corresponding to the passed code in the given table
245	   *
246	   * @param table the table used
247	   * @param code the code of the character
248	   */
249	  private static String getCharacter(Table table, int code) {
250	    switch (table) {
251	      case UPPER:
252	        return UPPER_TABLE[code];
253	      case LOWER:
254	        return LOWER_TABLE[code];
255	      case MIXED:
256	        return MIXED_TABLE[code];
257	      case PUNCT:
258	        return PUNCT_TABLE[code];
259	      case DIGIT:
260	        return DIGIT_TABLE[code];
261	      default:
262	        // Should not reach here.
263	        throw new IllegalStateException("Bad table");
264	    }
265	  }
