267	  static final class CorrectedBitsResult {
268	    private final boolean[] correctBits;
269	    private final int errorsCorrected;
270	    private final int ecLevel;
271	
272	    CorrectedBitsResult(boolean[] correctBits, int errorsCorrected, int ecLevel) {
273	      this.correctBits = correctBits;
274	      this.errorsCorrected = errorsCorrected;
275	      this.ecLevel = ecLevel;
276	    }
277	  }
278	
279	  /**
280	   * <p>Performs RS error correction on an array of bits.</p>
281	   *
282	   * @return the corrected array
283	   * @throws FormatException if the input contains too many errors
284	   */
285	  private CorrectedBitsResult correctBits(boolean[] rawbits) throws FormatException {
286	    GenericGF gf;
287	    int codewordSize;
288	
289	    if (ddata.getNbLayers() <= 2) {
290	      codewordSize = 6;
291	      gf = GenericGF.AZTEC_DATA_6;
292	    } else if (ddata.getNbLayers() <= 8) {
293	      codewordSize = 8;
294	      gf = GenericGF.AZTEC_DATA_8;
295	    } else if (ddata.getNbLayers() <= 22) {
296	      codewordSize = 10;
297	      gf = GenericGF.AZTEC_DATA_10;
298	    } else {
299	      codewordSize = 12;
300	      gf = GenericGF.AZTEC_DATA_12;
301	    }
302	
303	    int numDataCodewords = ddata.getNbDatablocks();
304	    int numCodewords = rawbits.length / codewordSize;
305	    if (numDataCodewords < 1 || numCodewords < numDataCodewords) {
306	      throw FormatException.getFormatInstance();
307	    }
308	    int offset = rawbits.length % codewordSize;
309	
310	    int[] dataWords = new int[numCodewords];
311	    for (int i = 0; i < numCodewords; i++, offset += codewordSize) {
312	      dataWords[i] = readCode(rawbits, offset, codewordSize);
313	    }
314	
315	    int errorsCorrected = 0;
316	    try {
317	      ReedSolomonDecoder rsDecoder = new ReedSolomonDecoder(gf);
318	      errorsCorrected = rsDecoder.decodeWithECCount(dataWords, numCodewords - numDataCodewords);
319	    } catch (ReedSolomonException ex) {
320	      throw FormatException.getFormatInstance(ex);
321	    }
322	
323	    // Now perform the unstuffing operation.
324	    // First, count how many bits are going to be thrown out as stuffing
325	    int mask = (1 << codewordSize) - 1;
326	    int stuffedBits = 0;
327	    for (int i = 0; i < numDataCodewords; i++) {
328	      int dataWord = dataWords[i];
329	      if (dataWord == 0 || dataWord == mask) {
330	        throw FormatException.getFormatInstance();
331	      } else if (dataWord == 1 || dataWord == mask - 1) {
332	        stuffedBits++;
333	      }
334	    }
335	    // Now, actually unpack the bits and remove the stuffing
336	    boolean[] correctedBits = new boolean[numDataCodewords * codewordSize - stuffedBits];
337	    int index = 0;
338	    for (int i = 0; i < numDataCodewords; i++) {
339	      int dataWord = dataWords[i];
340	      if (dataWord == 1 || dataWord == mask - 1) {
341	        // next codewordSize-1 bits are all zeros or all ones
342	        Arrays.fill(correctedBits, index, index + codewordSize - 1, dataWord > 1);
343	        index += codewordSize - 1;
344	      } else {
345	        for (int bit = codewordSize - 1; bit >= 0; --bit) {
346	          correctedBits[index++] = (dataWord & (1 << bit)) != 0;
347	        }
348	      }
349	    }
350	
351	    int ecLevel = 100 * (numCodewords - numDataCodewords) / numCodewords;
352	    return new CorrectedBitsResult(correctedBits, errorsCorrected, ecLevel);
353	  }
354	
355	  /**
356	   * Gets the array of bits from an Aztec Code matrix
357	   *
358	   * @return the array of bits
359	   */
360	  private boolean[] extractBits(BitMatrix matrix) throws FormatException {
361	    boolean compact = ddata.isCompact();
362	    int layers = ddata.getNbLayers();
363	    int baseMatrixSize = (compact ? 11 : 14) + layers * 4; // not including alignment lines
364	    int matrixSize = compact ? baseMatrixSize : baseMatrixSize + 1 + 2 * ((baseMatrixSize / 2 - 1) / 15);
365	    if (matrix.getHeight() != matrixSize || matrix.getWidth() != matrixSize) {
366	      // The matrix dimensions are fixed by the layer count; a mismatched detector result would
367	      // otherwise index outside the matrix below.
368	      throw FormatException.getFormatInstance();
369	    }
370	    int[] alignmentMap = new int[baseMatrixSize];
371	    boolean[] rawbits = new boolean[totalBitsInLayer(layers, compact)];
372	
373	    if (compact) {
374	      for (int i = 0; i < alignmentMap.length; i++) {
375	        alignmentMap[i] = i;
376	      }
377	    } else {
378	      int origCenter = baseMatrixSize / 2;
379	      int center = matrixSize / 2;
380	      for (int i = 0; i < origCenter; i++) {
381	        int newOffset = i + i / 15;
382	        alignmentMap[origCenter - i - 1] = center - newOffset - 1;
383	        alignmentMap[origCenter + i] = center + newOffset + 1;
384	      }
385	    }
386	    for (int i = 0, rowOffset = 0; i < layers; i++) {
387	      int rowSize = (layers - i) * 4 + (compact ? 9 : 12);
388	      // The top-left most point of this layer is <low, low> (not including alignment lines)
389	      int low = i * 2;
390	      // The bottom-right most point of this layer is <high, high> (not including alignment lines)
391	      int high = baseMatrixSize - 1 - low;
392	      // We pull bits from the two 2 x rowSize columns and two rowSize x 2 rows
393	      for (int j = 0; j < rowSize; j++) {
394	        int columnOffset = j * 2;
395	        for (int k = 0; k < 2; k++) {
396	          // left column
397	          rawbits[rowOffset + columnOffset + k] =
398	              matrix.get(alignmentMap[low + k], alignmentMap[low + j]);
399	          // bottom row
400	          rawbits[rowOffset + 2 * rowSize + columnOffset + k] =
401	              matrix.get(alignmentMap[low + j], alignmentMap[high - k]);
402	          // right column
403	          rawbits[rowOffset + 4 * rowSize + columnOffset + k] =
404	              matrix.get(alignmentMap[high - k], alignmentMap[high - j]);
405	          // top row
406	          rawbits[rowOffset + 6 * rowSize + columnOffset + k] =
407	              matrix.get(alignmentMap[high - j], alignmentMap[low + k]);
408	        }
409	      }
410	      rowOffset += rowSize * 8;
411	    }
412	    return rawbits;
413	  }
414	
415	  /**
416	   * Reads a code of given length and at given index in an array of bits
417	   */
418	  private static int readCode(boolean[] rawbits, int startIndex, int length) {
419	    int res = 0;
420	    for (int i = startIndex; i < startIndex + length; i++) {
421	      res <<= 1;
422	      if (rawbits[i]) {
423	        res |= 0x01;
424	      }
425	    }
426	    return res;
427	  }
428	
429	  /**
430	   * Reads a code of length 8 in an array of bits, padding with zeros
431	   */
432	  private static byte readByte(boolean[] rawbits, int startIndex) {
433	    int n = rawbits.length - startIndex;
434	    if (n >= 8) {
435	      return (byte) readCode(rawbits, startIndex, 8);
436	    }
437	    return (byte) (readCode(rawbits, startIndex, n) << (8 - n));
438	  }
439	
440	  /**
441	   * Packs a bit array into bytes, most significant bit first
442	   */
443	  static byte[] convertBoolArrayToByteArray(boolean[] boolArr) {
444	    byte[] byteArr = new byte[(boolArr.length + 7) / 8];
445	    for (int i = 0; i < byteArr.length; i++) {
446	      byteArr[i] = readByte(boolArr, 8 * i);
447	    }
448	    return byteArr;
449	  }
450	
451	  private static int totalBitsInLayer(int layers, boolean compact) {
452	    return ((compact ? 88 : 112) + 16 * layers) * layers;
453	  }
454	}
