30	 *
31	 * @author SITA Lab (kevin.osullivan@sita.aero)
32	 * @author Guenther Grau
33	 */
34	final class DecodedBitStreamParser {
35	
36	  private enum Mode {
37	    ALPHA,
38	    LOWER,
39	    MIXED,
40	    PUNCT,
41	    ALPHA_SHIFT,
42	    PUNCT_SHIFT
43	  }
44	
45	  private static final int TEXT_COMPACTION_MODE_LATCH = 900;
46	  private static final int BYTE_COMPACTION_MODE_LATCH = 901;
47	  private static final int NUMERIC_COMPACTION_MODE_LATCH = 902;
48	  private static final int BYTE_COMPACTION_MODE_LATCH_6 = 924;
49	  private static final int ECI_USER_DEFINED = 925;
50	  private static final int ECI_GENERAL_PURPOSE = 926;
51	  private static final int ECI_CHARSET = 927;
52	  private static final int BEGIN_MACRO_PDF417_CONTROL_BLOCK = 928;
53	  private static final int BEGIN_MACRO_PDF417_OPTIONAL_FIELD = 923;
54	  private static final int MACRO_PDF417_TERMINATOR = 922;
55	  private static final int READER_INITIALIZATION = 921;
56	  private static final int MODE_SHIFT_TO_BYTE_COMPACTION_MODE = 913;
57	  private static final int MAX_NUMERIC_CODEWORDS = 15;
58	
59	  private static final int MACRO_PDF417_OPTIONAL_FIELD_FILE_NAME = 0;
60	  private static final int MACRO_PDF417_OPTIONAL_FIELD_SEGMENT_COUNT = 1;
61	  private static final int MACRO_PDF417_OPTIONAL_FIELD_TIME_STAMP = 2;
62	  private static final int MACRO_PDF417_OPTIONAL_FIELD_SENDER = 3;
63	  private static final int MACRO_PDF417_OPTIONAL_FIELD_ADDRESSEE = 4;
64	  private static final int MACRO_PDF417_OPTIONAL_FIELD_FILE_SIZE = 5;
65	  private static final int MACRO_PDF417_OPTIONAL_FIELD_CHECKSUM = 6;
66	
67	  private static final int PL = 25;
68	  private static final int LL = 27;
69	  private static final int AS = 27;
70	  private static final int ML = 28;
71	  private static final int AL = 28;
72	  private static final int PS = 29;
73	  private static final int PAL = 29;
74	
75	  private static final char[] PUNCT_CHARS =
76	      ";<>@[\\]_`~!\r\t,:\n-.$/\"|*()?{}'".toCharArray();
77	
78	  private static final char[] MIXED_CHARS =
79	      "0123456789&\r\t,:#-.$/+%*=^".toCharArray();
80	
81	  /**
82	   * Table containing values for the exponent of 900.
83	   * This is used in the numeric compaction decode algorithm.
84	   */
85	  private static final BigInteger[] EXP900;
86	
87	  static {
88	    EXP900 = new BigInteger[16];
89	    EXP900[0] = BigInteger.ONE;
90	    BigInteger nineHundred = BigInteger.valueOf(900);
91	    EXP900[1] = nineHundred;
92	    for (int i = 2; i < EXP900.length; i++) {
93	      EXP900[i] = EXP900[i - 1].multiply(nineHundred);
94	    }
95	  }
96	
97	  private static final int NUMBER_OF_SEQUENCE_CODEWORDS = 2;
98	
99	  private DecodedBitStreamParser() {
100	  }
101	
102	  static DecoderResult decode(int[] codewords, String ecLevel) throws FormatException {
103	    int count = codewords[0];
104	    boolean readerInit = (codewords.length > 1 && codewords[1] == READER_INITIALIZATION);
105	    ECIStringBuilder result = new ECIStringBuilder(codewords.length * 2);
106	    int codeIndex = textCompaction(codewords, 1, result);
107	    PDF417ResultMetadata resultMetadata = new PDF417ResultMetadata();
108	    while (codeIndex < count) {
109	      int code = codewords[codeIndex++];
110	      switch (code) {
111	        case TEXT_COMPACTION_MODE_LATCH:
112	          codeIndex = textCompaction(codewords, codeIndex, result);
113	          break;
114	        case BYTE_COMPACTION_MODE_LATCH:
115	        case BYTE_COMPACTION_MODE_LATCH_6:
116	          codeIndex = byteCompaction(code, codewords, codeIndex, result);
117	          break;
118	        case MODE_SHIFT_TO_BYTE_COMPACTION_MODE:
119	          if (codeIndex >= count) {
120	            throw FormatException.getFormatInstance();
121	          }
122	          result.append((char) codewords[codeIndex++]);
123	          break;
124	        case NUMERIC_COMPACTION_MODE_LATCH:
125	          codeIndex = numericCompaction(codewords, codeIndex, result);
126	          break;
127	        case ECI_CHARSET:
128	          if (codeIndex >= count) {
129	            throw FormatException.getFormatInstance();
130	          }
131	          result.appendECI(codewords[codeIndex++]);
132	          break;
133	        case ECI_GENERAL_PURPOSE:
134	          // Can't do anything with generic ECI; skip its 2 characters
135	          codeIndex += 2;
136	          break;
137	        case ECI_USER_DEFINED:
138	          // Can't do anything with user ECI; skip its 1 character
139	          codeIndex++;
140	          break;
141	        case BEGIN_MACRO_PDF417_CONTROL_BLOCK:
142	          codeIndex = decodeMacroBlock(codewords, codeIndex, resultMetadata);
143	          break;
144	        case BEGIN_MACRO_PDF417_OPTIONAL_FIELD:
145	        case MACRO_PDF417_TERMINATOR:
146	          // Should not see these outside a macro block
147	          throw FormatException.getFormatInstance();
148	        default:
149	          // Default to text compaction. During testing numerous barcodes
150	          // appeared to be missing the starting mode. In these cases defaulting
151	          // to text compaction seems to work.
152	          codeIndex--;
153	          codeIndex = textCompaction(codewords, codeIndex, result);
154	          break;
155	      }
156	    }
157	    if (result.isEmpty() && resultMetadata.getFileId() == null) {
158	      throw FormatException.getFormatInstance();
159	    }
160	    DecoderResult decoderResult = new DecoderResult(null, result.toString(), null, ecLevel);
161	    decoderResult.setOther(resultMetadata);
162	    decoderResult.setReaderInit(readerInit);
163	    return decoderResult;
164	  }
