166	  @SuppressWarnings("deprecation")
167	  static int decodeMacroBlock(int[] codewords, int codeIndex, PDF417ResultMetadata resultMetadata)
168	      throws FormatException {
169	    int maxLength = codewords[0];
170	    if (codeIndex + NUMBER_OF_SEQUENCE_CODEWORDS > maxLength) {
171	      // we must have at least two bytes left for the segment index
172	      throw FormatException.getFormatInstance();
173	    }
174	    int[] segmentIndexArray = new int[NUMBER_OF_SEQUENCE_CODEWORDS];
175	    for (int i = 0; i < NUMBER_OF_SEQUENCE_CODEWORDS; i++, codeIndex++) {
176	      segmentIndexArray[i] = codewords[codeIndex];
177	    }
178	    String segmentIndexString = decodeBase900toBase10(segmentIndexArray, NUMBER_OF_SEQUENCE_CODEWORDS);
179	    if (segmentIndexString.isEmpty()) {
180	      resultMetadata.setSegmentIndex(0);
181	    } else {
182	      try {
183	        resultMetadata.setSegmentIndex(Integer.parseInt(segmentIndexString));
184	      } catch (NumberFormatException nfe) {
185	        // too large; bad input?
186	        throw FormatException.getFormatInstance();
187	      }
188	    }
189	
190	    // Decoding the fileId codewords as 0-899 numbers, each 0-filled to width 3. This follows the spec
191	    // (See ISO/IEC 15438:2015 Annex H.6) and preserves all info, but some generators (e.g. TEC-IT) write
192	    // the fileId using text compaction, so in those cases the fileId will appear mangled.
193	    StringBuilder fileId = new StringBuilder();
194	    while (codeIndex < maxLength &&
195	           codeIndex < codewords.length &&
196	           codewords[codeIndex] != MACRO_PDF417_TERMINATOR &&
197	           codewords[codeIndex] != BEGIN_MACRO_PDF417_OPTIONAL_FIELD) {
198	      fileId.append(String.format(Locale.ROOT, "%03d", codewords[codeIndex]));
199	      codeIndex++;
200	    }
201	    if (fileId.length() == 0) {
202	      // at least one fileId codeword is required (Annex H.2)
203	      throw FormatException.getFormatInstance();
204	    }
205	    resultMetadata.setFileId(fileId.toString());
206	
207	    int optionalFieldsStart = -1;
208	    if (codeIndex < maxLength && codewords[codeIndex] == BEGIN_MACRO_PDF417_OPTIONAL_FIELD) {
209	      optionalFieldsStart = codeIndex + 1;
210	    }
211	
212	    while (codeIndex < maxLength) {
213	      switch (codewords[codeIndex]) {
214	        case BEGIN_MACRO_PDF417_OPTIONAL_FIELD:
215	          codeIndex++;
216	          if (codeIndex >= maxLength) {
217	            throw FormatException.getFormatInstance();
218	          }
219	          switch (codewords[codeIndex]) {
220	            case MACRO_PDF417_OPTIONAL_FIELD_FILE_NAME:
221	              ECIStringBuilder fileName = new ECIStringBuilder();
222	              codeIndex = textCompaction(codewords, codeIndex + 1, fileName);
223	              resultMetadata.setFileName(fileName.toString());
224	              break;
225	            case MACRO_PDF417_OPTIONAL_FIELD_SENDER:
226	              ECIStringBuilder sender = new ECIStringBuilder();
227	              codeIndex = textCompaction(codewords, codeIndex + 1, sender);
228	              resultMetadata.setSender(sender.toString());
229	              break;
230	            case MACRO_PDF417_OPTIONAL_FIELD_ADDRESSEE:
231	              ECIStringBuilder addressee = new ECIStringBuilder();
232	              codeIndex = textCompaction(codewords, codeIndex + 1, addressee);
233	              resultMetadata.setAddressee(addressee.toString());
234	              break;
235	            case MACRO_PDF417_OPTIONAL_FIELD_SEGMENT_COUNT:
236	              ECIStringBuilder segmentCount = new ECIStringBuilder();
237	              codeIndex = numericCompaction(codewords, codeIndex + 1, segmentCount);
238	              try {
239	                resultMetadata.setSegmentCount(Integer.parseInt(segmentCount.toString()));
240	              } catch (NumberFormatException nfe) {
241	                throw FormatException.getFormatInstance();
242	              }
243	              break;
244	            case MACRO_PDF417_OPTIONAL_FIELD_TIME_STAMP:
245	              ECIStringBuilder timestamp = new ECIStringBuilder();
246	              codeIndex = numericCompaction(codewords, codeIndex + 1, timestamp);
247	              try {
248	                resultMetadata.setTimestamp(Long.parseLong(timestamp.toString()));
249	              } catch (NumberFormatException nfe) {
250	                throw FormatException.getFormatInstance();
251	              }
252	              break;
253	            case MACRO_PDF417_OPTIONAL_FIELD_CHECKSUM:
254	              ECIStringBuilder checksum = new ECIStringBuilder();
255	              codeIndex = numericCompaction(codewords, codeIndex + 1, checksum);
256	              try {
257	                resultMetadata.setChecksum(Integer.parseInt(checksum.toString()));
258	              } catch (NumberFormatException nfe) {
259	                throw FormatException.getFormatInstance();
260	              }
261	              break;
262	            case MACRO_PDF417_OPTIONAL_FIELD_FILE_SIZE:
263	              ECIStringBuilder fileSize = new ECIStringBuilder();
264	              codeIndex = numericCompaction(codewords, codeIndex + 1, fileSize);
265	              try {
266	                resultMetadata.setFileSize(Long.parseLong(fileSize.toString()));
267	              } catch (NumberFormatException nfe) {
268	                throw FormatException.getFormatInstance();
269	              }
270	              break;
271	            default:
272	              throw FormatException.getFormatInstance();
273	          }
274	          break;
275	        case MACRO_PDF417_TERMINATOR:
276	          codeIndex++;
277	          resultMetadata.setLastSegment(true);
278	          break;
279	        default:
280	          throw FormatException.getFormatInstance();
281	      }
282	    }
283	
284	    // copy optional fields to additional options
285	    if (optionalFieldsStart != -1) {
286	      int optionalFieldsLength = codeIndex - optionalFieldsStart;
287	      if (resultMetadata.isLastSegment()) {
288	        // do not include terminator
289	        optionalFieldsLength--;
290	      }
291	      if (optionalFieldsLength > 0) {
292	        resultMetadata.setOptionalData(Arrays.copyOfRange(codewords,
293	            optionalFieldsStart, optionalFieldsStart + optionalFieldsLength));
294	      }
295	    }
296	
297	    return codeIndex;
298	  }
