300	  /**
301	   * Text Compaction mode (see 5.4.1.5) permits all printable ASCII characters to be
302	   * encoded, i.e. values 32 - 126 inclusive in accordance with ISO/IEC 646 (IRV), as
303	   * well as selected control characters.
304	   *
305	   * @param codewords The array of codewords (data + error)
306	   * @param codeIndex The current index into the codeword array.
307	   * @param result    The decoded data is appended to the result.
308	   * @return The next index into the codeword array.
309	   */
310	  private static int textCompaction(int[] codewords, int codeIndex, ECIStringBuilder result) throws FormatException {
311	    // 2 character per codeword
312	    int[] textCompactionData = new int[(codewords[0] - codeIndex) * 2];
313	    // Used to hold the byte compaction value if there is a mode shift
314	    int[] byteCompactionData = new int[(codewords[0] - codeIndex) * 2];
315	
316	    int index = 0;
317	    boolean end = false;
318	    Mode subMode = Mode.ALPHA;
319	    while ((codeIndex < codewords[0]) && !end) {
320	      int code = codewords[codeIndex++];
321	      if (code < TEXT_COMPACTION_MODE_LATCH) {
322	        textCompactionData[index] = code / 30;
323	        textCompactionData[index + 1] = code % 30;
324	        index += 2;
325	      } else {
326	        switch (code) {
327	          case TEXT_COMPACTION_MODE_LATCH:
328	            // reinitialize text compaction mode to alpha sub mode
329	            textCompactionData[index++] = TEXT_COMPACTION_MODE_LATCH;
330	            break;
331	          case BYTE_COMPACTION_MODE_LATCH:
332	          case BYTE_COMPACTION_MODE_LATCH_6:
333	          case NUMERIC_COMPACTION_MODE_LATCH:
334	          case BEGIN_MACRO_PDF417_CONTROL_BLOCK:
335	          case BEGIN_MACRO_PDF417_OPTIONAL_FIELD:
336	          case MACRO_PDF417_TERMINATOR:
337	            codeIndex--;
338	            end = true;
339	            break;
340	          case MODE_SHIFT_TO_BYTE_COMPACTION_MODE:
341	            // The Mode Shift codeword 913 shall cause a temporary
342	            // switch from Text Compaction mode to Byte Compaction mode.
343	            // This switch shall be in effect for only the next codeword,
344	            // after which the mode shall revert to the prevailing sub-mode
345	            // of the Text Compaction mode. Codeword 913 is only available
346	            // in Text Compaction mode; its use is described in 5.4.2.4.
347	            textCompactionData[index] = MODE_SHIFT_TO_BYTE_COMPACTION_MODE;
348	            if (codeIndex >= codewords[0]) {
349	              throw FormatException.getFormatInstance();
350	            }
351	            code = codewords[codeIndex++];
352	            byteCompactionData[index] = code;
353	            index++;
354	            break;
355	          case ECI_CHARSET:
356	            if (codeIndex >= codewords[0]) {
357	              throw FormatException.getFormatInstance();
358	            }
359	            subMode = decodeTextCompaction(textCompactionData, byteCompactionData, index, result, subMode);
360	            result.appendECI(codewords[codeIndex++]);
361	            textCompactionData = new int[(codewords[0] - codeIndex) * 2];
362	            byteCompactionData = new int[(codewords[0] - codeIndex) * 2];
363	            index = 0;
364	            break;
365	        }
366	      }
367	    }
368	    decodeTextCompaction(textCompactionData, byteCompactionData, index, result, subMode);
369	    return codeIndex;
370	  }
