372	  /**
373	   * The Text Compaction mode includes all the printable ASCII characters
374	   * (i.e. values from 32 to 126) and three ASCII control characters: HT or tab
375	   * (ASCII value 9), LF or line feed (ASCII value 10), and CR or carriage
376	   * return (ASCII value 13). The Text Compaction mode also includes various latch
377	   * and shift characters which are used exclusively within the mode. The Text
378	   * Compaction mode encodes up to 2 characters per codeword. The compaction rules
379	   * for converting data into PDF417 codewords are defined in 5.4.2.2. The sub-mode
380	   * switches are defined in 5.4.2.3.
381	   *
382	   * @param textCompactionData The text compaction data.
383	   * @param byteCompactionData The byte compaction data if there
384	   *                           was a mode shift.
385	   * @param length             The size of the text compaction and byte compaction data.
386	   * @param result             The decoded data is appended to the result.
387	   * @param startMode          The mode in which decoding starts
388	   * @return The mode in which decoding ended
389	   */
390	  private static Mode decodeTextCompaction(int[] textCompactionData,
391	                                           int[] byteCompactionData,
392	                                           int length,
393	                                           ECIStringBuilder result,
394	                                           Mode startMode) {
395	    // Beginning from an initial state
396	    // The default compaction mode for PDF417 in effect at the start of each symbol shall always be Text
397	    // Compaction mode Alpha sub-mode (uppercase alphabetic). A latch codeword from another mode to the Text
398	    // Compaction mode shall always switch to the Text Compaction Alpha sub-mode.
399	    Mode subMode = startMode;
400	    Mode priorToShiftMode = startMode;
401	    Mode latchedMode = startMode;
402	    int i = 0;
403	    while (i < length) {
404	      int subModeCh = textCompactionData[i];
405	      char ch = 0;
406	      switch (subMode) {
407	        case ALPHA:
408	          // Alpha (uppercase alphabetic)
409	          if (subModeCh < 26) {
410	            // Upper case Alpha Character
411	            ch = (char) ('A' + subModeCh);
412	          } else {
413	            switch (subModeCh) {
414	              case 26:
415	                ch = ' ';
416	                break;
417	              case LL:
418	                subMode = Mode.LOWER;
419	                latchedMode = subMode;
420	                break;
421	              case ML:
422	                subMode = Mode.MIXED;
423	                latchedMode = subMode;
424	                break;
425	              case PS:
426	                // Shift to punctuation
427	                priorToShiftMode = subMode;
428	                subMode = Mode.PUNCT_SHIFT;
429	                break;
430	              case MODE_SHIFT_TO_BYTE_COMPACTION_MODE:
431	                result.append((char) byteCompactionData[i]);
432	                break;
433	              case TEXT_COMPACTION_MODE_LATCH:
434	                subMode = Mode.ALPHA;
435	                latchedMode = subMode;
436	                break;
437	            }
438	          }
439	          break;
440	
441	        case LOWER:
442	          // Lower (lowercase alphabetic)
443	          if (subModeCh < 26) {
444	            ch = (char) ('a' + subModeCh);
445	          } else {
446	            switch (subModeCh) {
447	              case 26:
448	                ch = ' ';
449	                break;
450	              case AS:
451	                // Shift to alpha
452	                priorToShiftMode = subMode;
453	                subMode = Mode.ALPHA_SHIFT;
454	                break;
455	              case ML:
456	                subMode = Mode.MIXED;
457	                latchedMode = subMode;
458	                break;
459	              case PS:
460	                // Shift to punctuation
461	                priorToShiftMode = subMode;
462	                subMode = Mode.PUNCT_SHIFT;
463	                break;
464	              case MODE_SHIFT_TO_BYTE_COMPACTION_MODE:
465	                result.append((char) byteCompactionData[i]);
466	                break;
467	              case TEXT_COMPACTION_MODE_LATCH:
468	                subMode = Mode.ALPHA;
469	                latchedMode = subMode;
470	                break;
471	            }
472	          }
473	          break;
474	
475	        case MIXED:
476	          // Mixed (numeric and some punctuation)
477	          if (subModeCh < PL) {
478	            ch = MIXED_CHARS[subModeCh];
479	          } else {
480	            switch (subModeCh) {
481	              case PL:
482	                subMode = Mode.PUNCT;
483	                latchedMode = subMode;
484	                break;
485	              case 26:
486	                ch = ' ';
487	                break;
488	              case LL:
489	                subMode = Mode.LOWER;
490	                latchedMode = subMode;
491	                break;
492	              case AL:
493	              case TEXT_COMPACTION_MODE_LATCH:
494	                subMode = Mode.ALPHA;
495	                latchedMode = subMode;
496	                break;
497	              case PS:
498	                // Shift to punctuation
499	                priorToShiftMode = subMode;
500	                subMode = Mode.PUNCT_SHIFT;
501	                break;
502	              case MODE_SHIFT_TO_BYTE_COMPACTION_MODE:
503	                result.append((char) byteCompactionData[i]);
504	                break;
505	            }
506	          }
507	          break;
508	
509	        case PUNCT:
510	          // Punctuation
511	          if (subModeCh < PAL) {
512	            ch = PUNCT_CHARS[subModeCh];
513	          } else {
514	            switch (subModeCh) {
515	              case PAL:
516	              case TEXT_COMPACTION_MODE_LATCH:
517	                subMode = Mode.ALPHA;
518	                latchedMode = subMode;
519	                break;
520	              case MODE_SHIFT_TO_BYTE_COMPACTION_MODE:
521	                result.append((char) byteCompactionData[i]);
522	                break;
523	            }
524	          }
525	          break;
526	
527	        case ALPHA_SHIFT:
528	          // Restore sub-mode
529	          subMode = priorToShiftMode;
530	          if (subModeCh < 26) {
531	            ch = (char) ('A' + subModeCh);
532	          } else {
533	            switch (subModeCh) {
534	              case 26:
535	                ch = ' ';
536	                break;
537	              case TEXT_COMPACTION_MODE_LATCH:
538	                subMode = Mode.ALPHA;
539	                break;
540	            }
541	          }
542	          break;
543	
544	        case PUNCT_SHIFT:
545	          // Restore sub-mode
546	          subMode = priorToShiftMode;
547	          if (subModeCh < PAL) {
548	            ch = PUNCT_CHARS[subModeCh];
549	          } else {
550	            switch (subModeCh) {
551	              case PAL:
552	              case TEXT_COMPACTION_MODE_LATCH:
553	                subMode = Mode.ALPHA;
554	                break;
555	              case MODE_SHIFT_TO_BYTE_COMPACTION_MODE:
556	                // PS before Shift-to-Byte is used as a padding character,
557	                // see 5.4.2.4 of the specification
558	                result.append((char) byteCompactionData[i]);
559	                break;
560	            }
561	          }
562	          break;
563	      }
564	      if (ch != 0) {
565	        // Append decoded character to result
566	        result.append(ch);
567	      }
568	      i++;
569	    }
570	    return latchedMode;
571	  }
