573	  /**
574	   * Byte Compaction mode (see 5.4.3) permits all 256 possible 8-bit byte values to be encoded.
575	   * This includes all ASCII characters value 0 to 127 inclusive and provides for international
576	   * character set support.
577	   *
578	   * @param mode      The byte compaction mode i.e. 901 or 924
579	   * @param codewords The array of codewords (data + error)
580	   * @param codeIndex The current index into the codeword array.
581	   * @param result    The decoded data is appended to the result.
582	   * @return The next index into the codeword array.
583	   */
584	  private static int byteCompaction(int mode,
585	                                    int[] codewords,
586	                                    int codeIndex,
587	                                    ECIStringBuilder result) throws FormatException {
588	    boolean end = false;
589	
590	    while (codeIndex < codewords[0] && !end) {
591	      //handle leading ECIs
592	      while (codeIndex < codewords[0] && codewords[codeIndex] == ECI_CHARSET) {
593	        if (codeIndex + 1 >= codewords[0]) {
594	          throw FormatException.getFormatInstance();
595	        }
596	        result.appendECI(codewords[++codeIndex]);
597	        codeIndex++;
598	      }
599	
600	      if (codeIndex >= codewords[0] || codewords[codeIndex] >= TEXT_COMPACTION_MODE_LATCH) {
601	        end = true;
602	      } else {
603	        //decode one block of 5 codewords to 6 bytes
604	        long value = 0;
605	        int count = 0;
606	        do {
607	          value = 900 * value + codewords[codeIndex++];
608	          count++;
609	        } while (count < 5 &&
610	                 codeIndex < codewords[0] &&
611	                 codewords[codeIndex] < TEXT_COMPACTION_MODE_LATCH);
612	        if (count == 5 && (mode == BYTE_COMPACTION_MODE_LATCH_6 ||
613	                           codeIndex < codewords[0] &&
614	                           codewords[codeIndex] < TEXT_COMPACTION_MODE_LATCH)) {
615	          for (int i = 0; i < 6; i++) {
616	            result.append((byte) (value >> (8 * (5 - i))));
617	          }
618	        } else {
619	          codeIndex -= count;
620	          while ((codeIndex < codewords[0]) && !end) {
621	            int code = codewords[codeIndex++];
622	            if (code < TEXT_COMPACTION_MODE_LATCH) {
623	              result.append((byte) code);
624	            } else if (code == ECI_CHARSET) {
625	              if (codeIndex >= codewords[0]) {
626	                throw FormatException.getFormatInstance();
627	              }
628	              result.appendECI(codewords[codeIndex++]);
629	            } else {
630	              codeIndex--;
631	              end = true;
632	            }
633	          }
634	        }
635	      }
636	    }
637	    return codeIndex;
638	  }
