640	  /**
641	   * Numeric Compaction mode (see 5.4.4) permits efficient encoding of numeric data strings.
642	   *
643	   * @param codewords The array of codewords (data + error)
644	   * @param codeIndex The current index into the codeword array.
645	   * @param result    The decoded data is appended to the result.
646	   * @return The next index into the codeword array.
647	   */
648	  private static int numericCompaction(int[] codewords, int codeIndex, ECIStringBuilder result) throws FormatException {
649	    int count = 0;
650	    boolean end = false;
651	
652	    int[] numericCodewords = new int[MAX_NUMERIC_CODEWORDS];
653	
654	    while (codeIndex < codewords[0] && !end) {
655	      int code = codewords[codeIndex++];
656	      if (codeIndex == codewords[0]) {
657	        end = true;
658	      }
659	      if (code < TEXT_COMPACTION_MODE_LATCH) {
660	        numericCodewords[count] = code;
661	        count++;
662	      } else {
663	        switch (code) {
664	          case TEXT_COMPACTION_MODE_LATCH:
665	          case BYTE_COMPACTION_MODE_LATCH:
666	          case BYTE_COMPACTION_MODE_LATCH_6:
667	          case BEGIN_MACRO_PDF417_CONTROL_BLOCK:
668	          case BEGIN_MACRO_PDF417_OPTIONAL_FIELD:
669	          case MACRO_PDF417_TERMINATOR:
670	          case ECI_CHARSET:
671	            codeIndex--;
672	            end = true;
673	            break;
674	        }
675	      }
676	      if ((count % MAX_NUMERIC_CODEWORDS == 0 || code == NUMERIC_COMPACTION_MODE_LATCH || end) && count > 0) {
677	        // Re-invoking Numeric Compaction mode (by using codeword 902
678	        // while in Numeric Compaction mode) serves  to terminate the
679	        // current Numeric Compaction mode grouping as described in 5.4.4.2,
680	        // and then to start a new one grouping.
681	        result.append(decodeBase900toBase10(numericCodewords, count));
682	        count = 0;
683	      }
684	    }
685	    return codeIndex;
686	  }
687	
688	  /**
689	   * Convert a list of Numeric Compacted codewords from Base 900 to Base 10.
690	   *
691	   * @param codewords The array of codewords
692	   * @param count     The number of codewords
693	   * @return The decoded string representing the Numeric data.
694	   */
695	  /*
696	     EXAMPLE
697	     Encode the fifteen digit numeric string 000213298174000
698	     Prefix the numeric string with a 1 and set the initial value of
699	     t = 1 000 213 298 174 000
700	     Calculate codeword 0
701	     d0 = 1 000 213 298 174 000 mod 900 = 200
702	
703	     t = 1 000 213 298 174 000 div 900 = 1 111 348 109 082
704	     Calculate codeword 1
705	     d1 = 1 111 348 109 082 mod 900 = 282
706	
707	     t = 1 111 348 109 082 div 900 = 1 234 831 232
708	     Calculate codeword 2
709	     d2 = 1 234 831 232 mod 900 = 632
710	
711	     t = 1 234 831 232 div 900 = 1 372 034
712	     Calculate codeword 3
713	     d3 = 1 372 034 mod 900 = 434
714	
715	     t = 1 372 034 div 900 = 1 524
716	     Calculate codeword 4
717	     d4 = 1 524 mod 900 = 624
718	
719	     t = 1 524 div 900 = 1
720	     Calculate codeword 5
721	     d5 = 1 mod 900 = 1
722	     t = 1 div 900 = 0
723	     Codeword sequence is: 1, 624, 434, 632, 282, 200
724	
725	     Decode the above codewords involves
726	       1 x 900 power of 5 + 624 x 900 power of 4 + 434 x 900 power of 3 +
727	     632 x 900 power of 2 + 282 x 900 power of 1 + 200 x 900 power of 0 = 1000213298174000
728	
729	     Remove leading 1 =>  Result is 000213298174000
730	   */
731	  private static String decodeBase900toBase10(int[] codewords, int count) throws FormatException {
732	    BigInteger result = BigInteger.ZERO;
733	    for (int i = 0; i < count; i++) {
734	      result = result.add(EXP900[count - i - 1].multiply(BigInteger.valueOf(codewords[i])));
